'use strict';
const assert=require('node:assert/strict');
const fs=require('node:fs');
const code=fs.readFileSync('modules/supplier/script-022.js','utf8');
const css=fs.readFileSync('styles/yardon-dock-timeline-v2.css','utf8');
const html=fs.readFileSync('index.html','utf8');
const start=code.indexOf('function renderDailyMap(){');
const end=code.indexOf('function refreshDailyMapLiveStatus()',start);
assert(start>=0&&end>start,'Daily map renderer exists');
const render=code.slice(start,end);
for(const s of ['yardon-dock-timeline','ydt-ramp','ydt-time','ydt-event','operationalPlanClass(a)','operationalPlanStatus(a)','yardivoMapDelayLabel(a)','data-announcement-id','data-move-dock','data-move-time','dmv-booked','dmv-ramp-head','renderDailyRampCapacity()'])assert(render.includes(s),'Missing critical timeline feature: '+s);
assert(render.includes('prior.outerHTML===child.outerHTML'),'unchanged cells retain DOM identity');
assert(render.includes('grid.children[i].remove()'),'stale cells are removed');
assert(!render.includes('grid.innerHTML='),'no full redraw when grid exists');
